x.append(R(6497459,"क्लासिक इटैलियन मरीनारा होल व्हीट पास्ता के साथ","आप अपनी मरीनारा सॉस बाज़ार की बोतलबंद सॉस की क़ीमत के एक छोटे हिस्से में खुद बना सकते हैं। यह सॉस लहसुन पर बहुत निर्भर है, लेकिन चाहें तो इस तेज़ स्वाद को कम कर सकते हैं। या तो लहसुन की मात्रा घटाएँ या लहसुन को बारीक काटने की बजाय स्लाइस करें। लहसुन को जितना ज़्यादा काटा या कूटा जाए, आपका अंतिम व्यंजन उतना ही तीखा होगा। लहसुन के बड़े टुकड़े, स्वादिष्ट रहते हुए भी, ज़्यादा हल्का स्वाद छोड़ते हैं। यह सॉस फ्रीज़ करने पर बहुत अच्छी रहती है। इसे मोटे ज़िप-लॉक फ्रीज़र बैग में डालें और 6 महीने तक रखें।","10","1/2 कप",
["2 बड़े चम्मच ऑलिव ऑयल","5 कली लहसुन (बारीक कटी हुई)","1 (28 औंस) कैन डिब्बाबंद टमाटर (अच्छी गुणवत्ता के, बेहतर हो तो अपने ही रस में पैक किए हुए, निथारे हुए, तरल अलग रखें)","5 पत्ते ताज़ी तुलसी (कटी हुई, या चाहें तो साबुत रखें)","10 औंस होल व्हीट पास्ता (पेने, शेल्स, फ्यूज़िली)","1/4 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च (ताज़ी पिसी हुई)","1/4 छोटा चम्मच पिसी लाल मिर्च के फ्लेक्स (वैकल्पिक)","2 बड़े चम्मच परमेसन या रोमानो चीज़ (ताज़ा कद्दूकस किया हुआ)"],
["ढक्कन वाली बड़ी कड़ाही में धीमी आंच पर ऑलिव ऑयल और लहसुन गरम करें (गहरे बर्तन का उपयोग न करें, आप चाहते हैं कि पानी जल्दी सूखे और सॉस गाढ़ी हो जाए)। लहसुन को बीच-बीच में चलाते हुए लगभग 6-7 मिनट पकाएँ, लेकिन भूरा न होने दें।","इस बीच, निथारे हुए टमाटर को एक गहरे कटोरे में डालें। टमाटर को हाथों से मोटा-मोटा कुचलें। टमाटर और तुलसी को कड़ाही में डालें और गाढ़ा होने तक 20-25 मिनट हल्की आंच पर पकाएँ। अगर सॉस बहुत गाढ़ी हो तो टमाटर के कैन से अलग रखे तरल में से थोड़ा डालें।","इस बीच 3-5 क्वार्ट के बर्तन में हल्के नमक वाला पानी (बर्तन को 2/3 भरें) तेज़ उबाल पर लाएँ। पास्ता डालें और पहले मिनट चलाएँ। पास्ता को लगभग 7-8 मिनट अल डेंटे होने तक पकाते रहें। निथार लें, धोएँ नहीं।","टमाटर की सॉस में नमक, काली मिर्च और, अगर उपयोग कर रहे हों, कुटी लाल मिर्च डालें। पास्ता को सॉस में डालें, ढक दें और पास्ता को 1-2 मिनट सॉस में रहने दें। पास्ता को गरम किए हुए कटोरे में डालें और चीज़ छिड़कें। (सॉस को फ्रीज़ भी किया जा सकता है। 1 क्वार्ट के डिब्बे में फ्रीज़ करें और 3-4 महीने तक रखें।)"]))
x.append(R(6497482,"ब्रुशेटा भरे मशरूम","ब्रुशेटा किसी भी जमावड़े के लिए एक रंग-बिरंगा और स्वादिष्ट स्टार्टर है। कम कार्ब विकल्प के लिए, इस सरल ब्रुशेटा को पारंपरिक बैगेट पर परोसने की बजाय मशरूम में भरकर आज़माएँ। यह रेसिपी द डायबिटीज़ सुपरफ़ूड्स कुकबुक एंड मील प्लानर में मिल सकती है।","7","2 मशरूम कैप",
["1 पिंट अंगूर के आकार के टमाटर","2 छोटे चम्मच ऑलिव ऑयल","2 कली लहसुन","2 छोटे चम्मच सूखी तुलसी","1/3 कप 2% मोत्ज़ारेला चीज़ (कद्दूकस किया हुआ)","2 बड़े चम्मच ताज़ा कद्दूकस किया परमेसन चीज़","14 औंस (लगभग 14 मशरूम) बड़े \"स्टफर\" मशरूम","1 बड़ा चम्मच बाल्समिक सिरका"],
["ओवन को पहले से 350°F पर गरम करें। टमाटर को चार टुकड़ों में काटकर एक तरफ रख दें।","एक कड़ाही में ऑलिव ऑयल गरम करें और लहसुन डालें। लहसुन को लगभग 1 मिनट भूनें। टमाटर डालें और लगभग 4 मिनट भूनना जारी रखें। आंच से उतारें और तुलसी और दोनों चीज़ मिलाएँ।","मशरूम के डंठल निकालें और टमाटर के मिश्रण से भरें। ओवन में 15 मिनट बेक करें।","थोड़ा ठंडा होने दें, फिर ऊपर से बाल्समिक सिरका डालें। गरमागरम परोसें।"]))
x.append(R(6498928,"ग्लूटेन-मुक्त चॉकलेट बनाना मफिन","ऐसा ग्लूटेन-मुक्त बेकिंग मिक्स उपयोग करने की कोशिश करें जिसमें ब्राउन राइस आटा पहली सामग्री के रूप में लिखा हो, ताकि आपका साबुत अनाज का सेवन बढ़े।","12","1 मफिन",
["2 स्प्रे, 0.5 ग्राम नॉनस्टिक कुकिंग स्प्रे","1/4 कप कैनोला तेल","1/2 कप 1:1 बेकिंग चीनी का विकल्प","1 छोटा चम्मच वैनिला एक्सट्रैक्ट","2 मध्यम पके केले (मसले हुए)","2 बड़े अंडे","1 कप ऑल-पर्पज़ ग्लूटेन-मुक्त बेकिंग मिक्स ((जैसे किंग आर्थर बेकिंग मिक्स))","1/2 कप ग्लूटेन-मुक्त, पुराने ढंग के रोल्ड ओट्स","1/2 कप कोको पाउडर","1 बड़ा चम्मच पानी","2 बड़े चम्मच मिनी चॉकलेट चिप्स"],
["ओवन को पहले से 350 डिग्री F पर गरम करें। मफिन टिन में मफिन पेपर लगाएँ और पेपर पर कुकिंग स्प्रे करें।","एक बड़े कटोरे में तेल, चीनी का विकल्प और वैनिला मिलाएँ। केले और अंडे एक-एक करके डालें। अच्छी तरह मिलाएँ।","बेकिंग मिक्स, ओट्स, कोको पाउडर और पानी मिलाएँ।","बैटर को 12 मफिन कपों में डालें। हर मफिन के ऊपर मिनी चॉकलेट चिप्स डालें (सभी मफिन पर बराबर बाँटें)।","20-22 मिनट या बीच में डाली गई टूथपिक साफ़ बाहर आने तक बेक करें।","ओवन से निकालें और मफिन को टिन में 10 मिनट ठंडा होने दें। मफिन को टिन से निकालें और वायर रैक पर पूरी तरह ठंडा करें।"]))
x.append(R(6499683,"व्हिप्ड रिकोटा और चाइव्स वाले मूली टोस्ट","अगर आप एवोकाडो टोस्ट के शौकीन हैं, तो इस मूली टोस्ट से कुछ नया करें! मधुमेह के अनुकूल और पेट भरने वाली यह रेसिपी नाश्ते या ब्रंच के रूप में परोसने के लिए बढ़िया है।","4","1 स्लाइस टोस्ट",
["4 स्लाइस राई ब्रेड","2 साबुत मूली (ऊपरी पत्ते हटाए हुए)","1/2 गुच्छा ताज़ा चाइव्स","8 औंस रिकोटा चीज़ (कम वसा वाला)"],
["ब्रेड को ब्रॉइलर के नीचे या टोस्टर में टोस्ट करें।","रिकोटा चीज़ और चाइव्स (सजावट के लिए कुछ चाइव्स बचाकर रखें) को ब्लेंडर या फ़ूड प्रोसेसर में चिकना होने तक प्यूरी करें। एक तरफ रख दें।","मूली को सावधानी से (अगर आपके पास मैंडोलिन है तो उसका उपयोग करें) 1/8 इंच मोटे गोल स्लाइस में काटें।","चीज़ और चाइव्स के मिश्रण को 4 ब्रेड स्लाइस में बाँटें और बराबर परत में चिकना करें।","चीज़ के ऊपर मूली के स्लाइस और बची हुई कटी चाइव्स डालें। चाहें तो काली मिर्च छिड़कें।"]))
x.append(R(6499693,"होल व्हीट पिटा","होल व्हीट पिटा की पोषण संबंधी जानकारी","1","2 औंस (4 इंच) का पिटा",["2 औंस (4 इंच) का होल व्हीट पिटा"],[]))
x.append(R(6499860,"परमेसन के साथ भुनी शतावरी","शतावरी शुरुआती वसंत में उगने वाली पहली हरी सब्ज़ियों में से एक है। यह एक सरल रेसिपी है जो इन डंडियों को चमकने देती है! इन्हें काली मिर्च और नींबू के ज़ेस्ट से मसालेदार बनाया जाता है, फिर ताज़े नींबू के रस और ऊपर से परमेसन छिड़ककर तैयार किया जाता है।","6","1/2 कप (5-6 डंडियाँ)",
["2 पाउंड शतावरी","1 छोटा चम्मच ऑलिव ऑयल","1/4 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच नींबू का ज़ेस्ट","2 बड़े चम्मच परमेसन चीज़ (कद्दूकस किया हुआ)","1 बड़ा चम्मच नींबू का रस"],
["ओवन को पहले से 425°F पर गरम करें। बेकिंग शीट पर बेकिंग पेपर बिछाएँ। शतावरी के सख़्त सिरे तोड़कर फेंक दें।","एक बड़े कटोरे में शतावरी को ऑलिव ऑयल, काली मिर्च और नींबू के ज़ेस्ट के साथ मिलाएँ।","शतावरी को तैयार बेकिंग शीट पर एक परत में रखें। 15 मिनट या नरम होने तक बेक करें। ओवन से निकालें, फिर चीज़ और नींबू का रस छिड़कें।"]))
x.append(R(6500091,"दालचीनी-मेपल ग्रिल्ड आड़ू","किसने कहा कि मिठाइयाँ ग्रिल नहीं की जा सकतीं? इस सरल व्यंजन को कुछ ताज़ी पुदीने की पत्तियों से सजाकर और आकर्षक बनाएँ।","4","1 आड़ू",
["4 आड़ू या नेक्टेरिन (अभी सख़्त लेकिन पके हुए)","1 नींबू का रस","1/2 छोटा चम्मच पिसी दालचीनी","1/8 छोटा चम्मच पिसा जायफल","1 बड़ा चम्मच मेपल सिरप"],
["आड़ू को आधा काटें और गुठली निकाल दें। आड़ू के आधे हिस्सों को दोबारा बंद होने वाले प्लास्टिक बैग में रखें।","एक छोटे कटोरे में नींबू का रस, दालचीनी, जायफल और मेपल सिरप मिलाएँ। मिश्रण को बैग में आड़ू पर डालें। बैग को बंद करें और आड़ू को लपेटने के लिए पलटें।","ग्रिल को मध्यम-तेज़ पर पहले से गरम करें। 4–5 मिनट पकाएँ, एक बार पलटते हुए, जब तक बाहर से सुनहरा भूरा और अंदर से बस गरम न हो जाए।"]))
x.append(R(6500455,"चॉकलेट पीनट बटर चिया सीड पुडिंग","यह पुडिंग दो लोगों के लिए एक ख़ास मिठाई बनने जितनी लाजवाब है, या नाश्ते या दोपहर के स्नैक के लिए इतनी हल्की है। चिया सीड्स मधुमेह के लिए सुपरफ़ूड हैं। इनमें फाइबर और ओमेगा-3 फैटी एसिड भरपूर होते हैं, जो ब्लड ग्लूकोज (रक्त शर्करा) प्रबंधन और हृदय स्वास्थ्य के लिए बढ़िया हैं। तरल के साथ मिलाने पर ये जेल बनाते हैं जिससे पुडिंग जैसी बनावट बनती है। इसे वीगन बनाने के लिए बादाम या सोया जैसे गैर-डेयरी दूध का उपयोग करें।","3","1/3 कप",
["2 बड़े चम्मच बिना मीठा कोको पाउडर","2 बड़े चम्मच कम या शून्य कैलोरी वाला स्वीटनर","1/4 कप पाउडर वाला पीनट बटर","1/4 कप चिया सीड्स","1 कप स्किम दूध या बिना मीठा बादाम दूध","1 छोटा चम्मच वैनिला एक्सट्रैक्ट"],
["कोको पाउडर, कम या शून्य कैलोरी वाला स्वीटनर और पाउडर पीनट बटर को आपस में मिलाएँ, और अच्छी तरह घोलें ताकि कोई गाँठ न रहे।","चिया सीड्स डालें और अच्छी तरह मिलाएँ।","दूध और वैनिला फेंटकर मिलाएँ। 5 मिनट रखा रहने दें, फिर दोबारा फेंटें। ढककर परोसने से पहले कम से कम 2 घंटे रेफ्रिजरेटर में रखें।"]))
